import{_ as t,o as a,c as i,ae as n}from"./chunks/framework.CK6jtcgr.js";const p=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),o={name:"guide/getting-started.md"};function r(d,e,l,s,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>SocioProphet is not open for ambient self-serve subscriptions.</p><p>The platform is being introduced through guided onboarding, institutional deployment, and public-safe documentation. That is intentional. The system is designed as a governed operational stack, not as an unbounded sign-up funnel.</p><h2 id="_1-start-with-the-right-path" tabindex="-1">1. Start with the right path <a class="header-anchor" href="#_1-start-with-the-right-path" aria-label="Permalink to &quot;1. Start with the right path&quot;">​</a></h2><p>Pick the path that matches what you are actually trying to do.</p><h3 id="learning-and-exploration" tabindex="-1">Learning and exploration <a class="header-anchor" href="#learning-and-exploration" aria-label="Permalink to &quot;Learning and exploration&quot;">​</a></h3><p>Use this path when the goal is to understand the architecture, the learning model, and the public-safe theory.</p><p>Read:</p><ul><li><a href="/documentation/guide/architecture">Architecture</a></li><li><a href="/documentation/guide/operating-modes-learning-and-defense">Operating Modes: Learning and Defense</a></li><li><a href="/documentation/guide/twenty-three-topic-canon">23-Topic Canon</a></li></ul><h3 id="institutional-deployment" tabindex="-1">Institutional deployment <a class="header-anchor" href="#institutional-deployment" aria-label="Permalink to &quot;Institutional deployment&quot;">​</a></h3><p>Use this path when evaluating SocioProphet for an organization, program, mission-aligned institution, or governed operational environment.</p><p>Read:</p><ul><li><a href="/documentation/guide/organizations-governance-and-institutional-safety">Organizations Governance and Institutional Safety</a></li><li><a href="/documentation/guide/deterministic-ai-and-mathematical-safety">Deterministic AI and Mathematical Safety</a></li><li><a href="/documentation/guide/public-vs-restricted-security-boundary">Public vs Restricted Security Boundary</a></li></ul><p>Then go to:</p><ul><li><a href="https://socioprophet.com/organizations/" target="_blank" rel="noreferrer">Organizations landing page</a></li><li><a href="https://socioprophet.com/organizations/apply/" target="_blank" rel="noreferrer">Organizations intake</a></li></ul><h3 id="analytics-identity-and-evidence" tabindex="-1">Analytics, identity, and evidence <a class="header-anchor" href="#analytics-identity-and-evidence" aria-label="Permalink to &quot;Analytics, identity, and evidence&quot;">​</a></h3><p>Use this path when the main interest is governed identity, merge controls, event modeling, proof artifacts, and boundary evidence.</p><p>Read:</p><ul><li><a href="/documentation/guide/entity-analytics-reference">Entity Analytics Reference</a></li><li><a href="/documentation/guide/worked-example-michael-cross-context">Worked Example: Michael Cross-Context</a></li><li><a href="/documentation/guide/boundary-centric-cyber-hypergraph">Boundary-Centric Cyber Hypergraph</a></li></ul><h3 id="governed-operations-and-defense" tabindex="-1">Governed operations and defense <a class="header-anchor" href="#governed-operations-and-defense" aria-label="Permalink to &quot;Governed operations and defense&quot;">​</a></h3><p>Use this path when the interest is bounded execution, operator workflows, defensive validation, and governance of sensitive capability.</p><p>Read:</p><ul><li><a href="/documentation/guide/governed-ai-and-cybernetics">Governed AI and Cybernetics</a></li><li><a href="/documentation/guide/agent-plane-and-operator-workflows">Agent Plane and Operator Workflows</a></li><li><a href="/documentation/guide/authorized-cyberdefense-and-simulation">Authorized Cyberdefense and Simulation</a></li></ul><h2 id="_2-what-the-public-docs-include" tabindex="-1">2. What the public docs include <a class="header-anchor" href="#_2-what-the-public-docs-include" aria-label="Permalink to &quot;2. What the public docs include&quot;">​</a></h2><p>The public docs include:</p><ul><li>architecture</li><li>governance</li><li>safety boundaries</li><li>bounded-execution model</li><li>evidence and provenance model</li><li>public-safe product positioning</li><li>institutional deployment framing</li></ul><h2 id="_3-what-the-public-docs-do-not-include" tabindex="-1">3. What the public docs do not include <a class="header-anchor" href="#_3-what-the-public-docs-do-not-include" aria-label="Permalink to &quot;3. What the public docs do not include&quot;">​</a></h2><p>The public docs do not include:</p><ul><li>sensitive operator kits</li><li>exact tactical playbooks</li><li>exploit or persistence workflows</li><li>high-fidelity adversary mechanics</li><li>restricted thresholds and internals that materially raise misuse value</li></ul><p>That line is deliberate and part of the system design.</p><h2 id="_4-recommended-reading-order" tabindex="-1">4. Recommended reading order <a class="header-anchor" href="#_4-recommended-reading-order" aria-label="Permalink to &quot;4. Recommended reading order&quot;">​</a></h2><p>For most readers, this order works:</p><ol><li><a href="/documentation/guide/architecture">Architecture</a></li><li><a href="/documentation/guide/deterministic-ai-and-mathematical-safety">Deterministic AI and Mathematical Safety</a></li><li><a href="/documentation/guide/organizations-governance-and-institutional-safety">Organizations Governance and Institutional Safety</a></li><li><a href="/documentation/guide/governed-ai-and-cybernetics">Governed AI and Cybernetics</a></li><li><a href="/documentation/guide/entity-analytics-reference">Entity Analytics Reference</a></li><li><a href="/documentation/guide/public-vs-restricted-security-boundary">Public vs Restricted Security Boundary</a></li></ol><h2 id="_5-use-this-page" tabindex="-1">5. Use this page <a class="header-anchor" href="#_5-use-this-page" aria-label="Permalink to &quot;5. Use this page&quot;">​</a></h2><p>Use this page to choose the right reading path.</p><p>Use the organizations pages for deployment conversations.</p><p>Use the docs landing surface for the broader manual map.</p><p>Use the public docs to understand the system honestly, including the parts we restrict.</p>',38)])])}const g=t(o,[["render",r]]);export{p as __pageData,g as default};
